<?php use App\Core\{Csrf,DataTableFormat,SecurityHeaders}; require BASE_PATH.'/app/Views/arpa_appointments/tabs.php'; ?>
<div class="page-heading"><div><div class="breadcrumb-lite">ARPA Officer Assignments / New</div><h1>New ARPA Division Assignment</h1><p>This assignment will be reviewed before it becomes current.</p><?php if($ascDerivedFromContext): ?><div class="text-muted"><strong>Agrarian Service Center:</strong> <?= e((string)$activeAsc['location_name']) ?><?php if(!empty($activeAsc['location_dad_number'])): ?> <span class="ms-1"><?= e((string)$activeAsc['location_dad_number']) ?></span><?php endif; ?></div><?php endif; ?></div></div>
<div class="alert alert-info">An officer must have service permanency recorded and an active Permanent ARPA Division before Acting, Duty Covering, or Attend to the Duty can be requested.</div>
