<?= Csrf::field() ?>
<div class="form-section"><h2 class="h5">Appointment Request</h2><div class="row g-3">
<?php if(!$ascDerivedFromContext): ?><div class="col-12"><label class="form-label" for="asc_location_id">Agrarian Service Center *</label><select class="form-select" id="asc_location_id" name="asc_location_id" required><option value="">Select Agrarian Service Center</option><?php foreach($ascs as $r): ?><option value="<?= e($r['id']) ?>" <?= $selectedAsc===$r['id']?'selected':'' ?>><?= e($r['dad_number'].' - '.$r['name_en']) ?></option><?php endforeach; ?></select></div><?php endif; ?>
